sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_audioLevel;
uniform float amzp_bass;
uniform float amzp_mid;
uniform float amzp_high;
uniform float amzp_bandMix;
uniform float amzp_bassCenter;
uniform float amzp_amp;
uniform float amzp_progressc;
uniform float amzp_wobble;
uniform float amzp_progressa;
uniform float amzp_evoSpeed;
uniform float amzp_style;
uniform float amzp_bars;
uniform float amzp_segments;
uniform float amzp_gapX;
uniform float amzp_gapY;
uniform float amzp_roundness;
uniform float amzp_ghost;
uniform float amzp_mirrorV;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float amzp_adaptive;
uniform float amzp_bright;
uniform float amzp_blendMode;
uniform float amzp_clipLayer;
uniform float amzp_alpha;
uniform float amzp_alphaComp;
    float h11(float n) { return fract(sin(n * 127.1 + 311.7) * 43758.5453); }
    float vn1(float x) {
        float i = floor(x), f = fract(x);
        f = f * f * (3.0 - 2.0 * f);
        return mix(h11(i), h11(i + 1.0), f);
    }
    float bandAt(float x) {
        float wb = 1.0 - smoothstep(0.0, 0.45, x);
        float wh = smoothstep(0.55, 1.0, x);
        float wm = max(0.0, 1.0 - wb - wh);
        return clamp(amzp_bass, 0.0, 1.0) * wb + clamp(amzp_mid, 0.0, 1.0) * wm + clamp(amzp_high, 0.0, 1.0) * wh;
    }
    float barLevel(float i, float N, float evo) {
        float g = (i + 0.5) / N;
        float x = (amzp_bassCenter>0.5) ? abs(g * 2.0 - 1.0) : g;
        float lv = mix(clamp(amzp_audioLevel, 0.0, 1.0), bandAt(x), clamp(amzp_bandMix, 0.0, 1.0));
        float2 hb = sin(float2(evo * 8.0) / float2(-2.5, 5.0) + float2(5.0, 2.0) * g * 5.0);
        float pat = hb.y * g * (1.0 - g) * 1.8 + hb.x * g * 0.3 + 0.5;
        float nz = vn1(i * 1.37 + evo * 3.0 + h11(i) * 7.0);
        float idle = clamp(0.55 * pat + 0.45 * nz + 0.1, 0.0, 1.0);
        float h = lv * mix(1.0, idle, clamp(amzp_wobble, 0.0, 1.0));
        h = clamp(h * max(amzp_amp, 0.0), 0.0, 1.0);
        return pow(h, 1.0 / max(amzp_progressc, 0.01));
    }
    float sdb(float2 q, float r) {
        q += r;
        return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
    }
    void amzRender() {
        float2 W = layer;
        float2 p = amzLayerNorm() * W;
        float4 src = amzTexture(0, amzScreenNorm());
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float2 base = (amzp_adaptive>0.5) ? W : float2(min(W.x, W.y));
        float2 A = base * max(amzp_scale, 0.01) * max(amzp_stretch, float2(0.01));
        float2 q = p - (W * 0.5 + float2(amzp_position.x, -amzp_position.y) * pxs);
        float an = radians(amzp_angle);
        float cs = cos(an), sn = sin(an);
        q = float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y);
        float2 u = q + A * 0.5;
        float N = max(floor(amzp_bars + 0.5), 1.0);
        float M = max(floor(amzp_segments + 0.5), 1.0);
        float2 cell = A / float2(N, M);
        float evo = amzp_progressa + time * amzp_evoSpeed;
        float cov = 0.0, lit = 0.0, t = 0.0;
        if (u.x > -2.0 && u.x < A.x + 2.0 && u.y > -2.0 && u.y < A.y + 2.0) {
            float i = clamp(floor(u.x / cell.x), 0.0, N - 1.0);
            float h = barLevel(i, N, evo);
            float bw = cell.x * (1.0 - clamp(amzp_gapX, 0.0, 0.95));
            float dx = abs(u.x - (i + 0.5) * cell.x) - bw * 0.5;
            float H = (amzp_mirrorV>0.5) ? A.y * 0.5 : A.y;
            float yv = (amzp_mirrorV>0.5) ? abs(u.y - A.y * 0.5) : u.y;
            t = clamp(yv / max(H, 1.0), 0.0, 1.0);
            if (int(amzp_style) == 1) {
                float hh = h * H;
                float cy = (amzp_mirrorV>0.5) ? 0.0 : hh * 0.5;
                float hlf = (amzp_mirrorV>0.5) ? hh : hh * 0.5;
                float r = clamp(amzp_roundness, 0.0, 1.0) * 0.5 * min(bw, max(hh * ((amzp_mirrorV>0.5) ? 2.0 : 1.0), 0.0));
                float d = sdb(float2(dx, abs(yv - cy) - hlf), r);
                float c1 = hh > 0.0 ? clamp(0.5 - d, 0.0, 1.0) : 0.0;
                float c0 = 0.0;
                if (amzp_ghost > 0.0) {
                    float cyT = (amzp_mirrorV>0.5) ? 0.0 : H * 0.5, hlfT = (amzp_mirrorV>0.5) ? H : H * 0.5;
                    float rT = clamp(amzp_roundness, 0.0, 1.0) * 0.5 * bw;
                    c0 = clamp(0.5 - sdb(float2(dx, abs(yv - cyT) - hlfT), rT), 0.0, 1.0) * clamp(amzp_ghost, 0.0, 1.0);
                }
                cov = max(c1, c0);
                lit = 1.0;
            } else {
                float nSeg = (amzp_mirrorV>0.5) ? max(floor(M * 0.5 + 0.5), 1.0) : M;
                float segH = H / nSeg;
                float j = floor(yv / segH);
                float sh = segH * (1.0 - clamp(amzp_gapY, 0.0, 0.95));
                float ly = yv - (j + 0.5) * segH;
                float d;
                if (int(amzp_style) == 2) {
                    float rad = 0.5 * min(bw, sh);
                    d = length(float2(u.x - (i + 0.5) * cell.x, ly)) - rad;
                } else {
                    float r = clamp(amzp_roundness, 0.0, 1.0) * 0.5 * min(bw, sh);
                    d = sdb(float2(dx, abs(ly) - sh * 0.5), r);
                }
                float inRange = (j >= 0.0 && j < nSeg) ? 1.0 : 0.0;
                cov = clamp(0.5 - d, 0.0, 1.0) * inRange;
                float nl = floor(h * nSeg + 0.5);
                lit = j < nl ? 1.0 : clamp(amzp_ghost, 0.0, 1.0);
                t = clamp((j + 0.5) / nSeg, 0.0, 1.0);
            }
        }
        float4 c = mix(amzp_color1, amzp_color2, t);
        float la = cov * lit * c.a;
        float3 L = c.rgb * la * max(amzp_bright, 0.0);
        float fa = clamp(amzp_alpha, 0.0, 1.0);
        if ((amzp_clipLayer>0.5)) { L *= src.a; la *= src.a; }
        L *= fa; la *= fa;
        float4 light = float4(min(L, float3(1.0)), la);
        float4 orig = src * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 1) o = float4(orig.rgb * (light.rgb + float3(1.0 - la)), orig.a);
        else if (int(amzp_blendMode) == 2) o = float4(orig.rgb + light.rgb - orig.rgb * light.rgb, max(orig.a, la));
        else if (int(amzp_blendMode) == 3) o = float4(orig.rgb + L, max(orig.a, la));
        else if (int(amzp_blendMode) == 4) o = light + orig * (1.0 - la);
        else o = light;
        o = clamp(o, 0.0, 1.0);
        amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
